const item = $input.all()[0];

return [{
  json: {
    id: item.json.device_id,
    auth_key: 'Mzg3ZDVmdWlkB2415D1B7F9AA0DEE25014600F3EEC3B5B84D0E846541BAC6C39A99DD81DAB09ED8C1B89DE9EEEEA',
    _dispositivo_id: item.json.id,
    _dispositivo_nombre: item.json.nombre,
    _dispositivo_modelo: item.json.modelo
  }
}];

// Obtener la respuesta del item actual
const response = $input.item.json;
// El dispositivo_id debe estar en las propiedades que guardamos
const dispositivo_id = $('Preparar Request Batch').first().json._dispositivo_id;
const dispositivo_nombre = response._dispositivo_nombre;
const dispositivo_modelo = response._dispositivo_modelo;

if (!response.isok || !response.data) {
  console.log(`Error en respuesta para ${dispositivo_nombre}`);
  return [];
}

const deviceStatus = response.data.device_status;
const emeters = deviceStatus.emeters || [];
const canal1 = emeters[0] || {};
const canal2 = emeters[1] || {};
const canal3 = emeters[2] || {};

const potenciaTotal = deviceStatus.total_power || 0;
const energiaTotal = (canal1.total || 0) + (canal2.total || 0) + (canal3.total || 0);
const energiaRetornadaTotal = (canal1.total_returned || 0) + (canal2.total_returned || 0) + (canal3.total_returned || 0);

// Crear fecha en timezone de Madrid
const fecha_lectura = new Date().toLocaleString('sv-SE', { 
  timeZone: 'Europe/Madrid',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
}).replace(',', '');

return [{
  json: {
    dispositivo_id: dispositivo_id,
    fecha_lectura: fecha_lectura,
    potencia_total_w: parseFloat(potenciaTotal),
    potencia_canal_1_w: parseFloat(canal1.power || 0),
    potencia_canal_2_w: parseFloat(canal2.power || 0),
    potencia_canal_3_w: parseFloat(canal3.power || 0),
    energia_total_kwh: parseFloat((energiaTotal / 1000).toFixed(2)),
    energia_retornada_kwh: parseFloat((energiaRetornadaTotal / 1000).toFixed(2)),
    energia_canal_1_kwh: parseFloat(((canal1.total || 0) / 1000).toFixed(2)),
    energia_canal_2_kwh: parseFloat(((canal2.total || 0) / 1000).toFixed(2)),
    energia_canal_3_kwh: parseFloat(((canal3.total || 0) / 1000).toFixed(2)),
    voltaje_canal_1: parseFloat(canal1.voltage || 0),
    voltaje_canal_2: parseFloat(canal2.voltage || 0),
    voltaje_canal_3: parseFloat(canal3.voltage || 0),
    voltaje_promedio: parseFloat((((canal1.voltage || 0) + (canal2.voltage || 0) + (canal3.voltage || 0)) / 3).toFixed(1)),
    corriente_canal_1: parseFloat(canal1.current || 0),
    corriente_canal_2: parseFloat(canal2.current || 0),
    corriente_canal_3: parseFloat(canal3.current || 0),
    corriente_neutro: parseFloat(deviceStatus.emeter_n?.current || 0),
    pf_canal_1: parseFloat(canal1.pf || 0),
    pf_canal_2: parseFloat(canal2.pf || 0),
    pf_canal_3: parseFloat(canal3.pf || 0),
    online: response.data.online ? 1 : 0,
    wifi_conectado: deviceStatus.wifi_sta?.connected ? 1 : 0,
    wifi_rssi: parseInt(deviceStatus.wifi_sta?.rssi) || null,
    cloud_conectado: deviceStatus.cloud?.connected ? 1 : 0,
    uptime_segundos: parseInt(deviceStatus.uptime) || null,
    canal_1_valido: canal1.is_valid ? 1 : 0,
    canal_2_valido: canal2.is_valid ? 1 : 0,
    canal_3_valido: canal3.is_valid ? 1 : 0,
    datos_raw: JSON.stringify(response.data)
  }
}];
